using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;
class SubtitleCancelChecks {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Get(Game game,string name){return typeof(Game).GetField(name,flags).GetValue(game);}
 static void Set(Game game,string name,object value){typeof(Game).GetField(name,flags).SetValue(game,value);}
 static object Call(Game game,string name,params object[] args){return typeof(Game).GetMethod(name,flags).Invoke(game,args);}
 [STAThread]static void Main(){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();using(var game=new Game()){game.Opacity=0;game.Show();Application.DoEvents();for(int run=0;run<6;run++){Set(game,"save",new Save());using(var close=new Timer{Interval=30}){close.Tick+=(s,e)=>{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="本节字幕与挑战模式");if(dialog!=null)dialog.Close();};close.Start();Action enter=()=>Call(game,"EnterTavern");if(run%2==0)Call(game,"NavigateMenu",enter,"序幕 · 第一盏灯",false,false,null);else enter();var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<2400){Application.DoEvents();System.Threading.Thread.Sleep(10);}if((string)Get(game,"page")!="waystation-map")throw new Exception("Cancellation did not return to map");if((bool)Get(game,"originalPlaying"))throw new Exception("Cancelled story started audio");var save=(Save)Get(game,"save");if(save.sectionAttempts.Values.Any(a=>a.subtitlesChosen))throw new Exception("Cancellation selected subtitles");Call(game,"PlayCurrent");if((bool)Get(game,"originalPlaying"))throw new Exception("Stale playback started on map");}}game.Close();}Console.WriteLine("PASS: six direct/loading cancellations, return to map, no subtitle choice or stale playback.");}
}
